css:
.mediums { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 16px; }
  .medium { background: #fff; border: 1px solid var(--line); border-radius: 14px; padding: 16px 18px; }
  .medium small { display: block; font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: var(--green); margin-bottom: 8px; }
  .medium p { font-size: 15px; line-height: 1.6; margin: 0; }
  .related { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 18px; }
  .related-card { display: grid; gap: 8px; align-content: start; background: #fff; border: 1px solid var(--line); border-radius: 14px; padding: 18px; text-decoration: none; color: var(--ink); }
  .related-card b { font-family: var(--serif); font-size: 20px; font-weight: 500; line-height: 1.2; }
  .related-card p { font-size: 14.5px; line-height: 1.55; margin: 0; color: var(--ink-2); }
  .pro-box { margin-top: 22px; padding: 26px 28px; border-radius: 18px; background: var(--ink); color: var(--cream); display: grid; grid-template-columns: 1fr auto; gap: 20px; align-items: center; }
  .pro-box h3 { color: #fff; font-size: 22px; margin-bottom: 8px; }
  .pro-box ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 6px; font-size: 15px; color: rgba(255,250,240,.8); }
  .pro-box li { display: flex; gap: 10px; align-items: baseline; }
  .pro-box li::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--peach); flex: 0 0 7px; }
  .pro-box .chip { background: rgba(255,250,240,.1); border-color: rgba(255,250,240,.25); color: var(--cream); margin-bottom: 10px; }
  @media (max-width: 820px) { .mediums, .related, .pro-box { grid-template-columns: 1fr; } }
